package com.cleardialogue;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws dialogue text in a bundled font (OpenDyslexic) for fonts the game doesn't have.
 *
 * The game's own text widgets stay in place, made fully transparent by the plugin, so every
 * click area and shortcut is unchanged. This overlay only redraws the same text inside each
 * widget's own bounds, following the widget's alignment.
 */
@Slf4j
class BundledFontOverlay extends Overlay
{
	private static final Pattern TAGS = Pattern.compile("<[^>]*>");
	private static final Pattern BREAKS = Pattern.compile("<br>", Pattern.CASE_INSENSITIVE);
	private static final int MIN_SIZE = 8;
	private static final int MAX_SIZE = 28;
	private static final int MAX_CACHED_LAYOUTS = 64;

	private static Font regular;
	private static Font bold;

	private final ClearDialoguePlugin plugin;
	private final ClearDialogueConfig config;

	/**
	 * Fitted layouts, so wrapping and shrink-to-fit run once per text rather than every frame.
	 */
	private final Map<String, Layout> layouts = new HashMap<>();

	@Inject
	BundledFontOverlay(ClearDialoguePlugin plugin, ClearDialogueConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		List<ClearDialoguePlugin.DrawnText> texts = plugin.getDrawnTexts();
		if (texts.isEmpty())
		{
			return null;
		}

		int size = Math.max(MIN_SIZE, Math.min(MAX_SIZE, config.bundledFontSize()));
		int spacing = Math.max(60, Math.min(150, config.bundledLineSpacing()));
		boolean shadow = config.shadow();
		for (ClearDialoguePlugin.DrawnText t : texts)
		{
			// Own copy of the graphics so font, colour, hints and clip don't leak into other overlays
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
				draw(g2, t.getWidget(), t.getText(), t.getColour(), t.isBold(), size, spacing, shadow);
			}
			finally
			{
				g2.dispose();
			}
		}
		return null;
	}

	private void draw(Graphics2D g, Widget w, String rawText, Color colour, boolean useBold,
		int maxSize, int spacing, boolean shadow)
	{
		String text = clean(rawText);
		Rectangle box = w.getBounds();
		if (text.isEmpty() || box == null || box.width <= 0 || box.height <= 0)
		{
			return;
		}

		String key = text + '\u0000' + box.width + 'x' + box.height + '/' + maxSize + '/' + spacing + '/' + useBold;
		Layout layout = layouts.get(key);
		if (layout == null)
		{
			if (layouts.size() >= MAX_CACHED_LAYOUTS)
			{
				layouts.clear();
			}
			layout = fit(g, text, box, maxSize, spacing, useBold);
			layouts.put(key, layout);
		}

		g.setFont(layout.font);
		FontMetrics fm = g.getFontMetrics();
		List<String> lines = layout.lines;
		int lineHeight = layout.lineHeight;
		// Keep overflow (text that can't fit even at the minimum size) inside the widget's box
		g.clip(new Rectangle(box.x - 2, box.y - 2, box.width + 4, box.height + 4));

		int blockHeight = (lines.size() - 1) * lineHeight + fm.getAscent() + fm.getDescent();
		int y;
		// If it can't fit even at the smallest size, start from the top so the beginning is readable
		switch (blockHeight > box.height + 4 ? 0 : w.getYTextAlignment())
		{
			case 0:
				y = box.y;
				break;
			case 2:
				y = box.y + box.height - blockHeight;
				break;
			default:
				y = box.y + (box.height - blockHeight) / 2;
				break;
		}
		y += fm.getAscent();

		for (String line : lines)
		{
			int width = fm.stringWidth(line);
			int x;
			switch (w.getXTextAlignment())
			{
				case 0:
					x = box.x;
					break;
				case 2:
					x = box.x + box.width - width;
					break;
				default:
					x = box.x + (box.width - width) / 2;
					break;
			}
			if (shadow)
			{
				g.setColor(Color.BLACK);
				g.drawString(line, x + 1, y + 1);
			}
			g.setColor(colour);
			g.drawString(line, x, y);
			y += lineHeight;
		}
	}

	/**
	 * Shrinks the font until the wrapped text fits the box.
	 */
	private static Layout fit(Graphics2D g, String text, Rectangle box, int maxSize, int spacing, boolean useBold)
	{
		int size = maxSize;
		while (true)
		{
			Font f = font(useBold).deriveFont((float) size);
			FontMetrics fm = g.getFontMetrics(f);
			int lineHeight = Math.max(1, Math.round(fm.getHeight() * spacing / 100f));
			List<String> lines = wrap(text, fm, box.width);
			// The last line only needs its glyphs to fit, with a little slack
			int needed = (lines.size() - 1) * lineHeight + fm.getAscent() + fm.getDescent();
			if (needed <= box.height + 4 || size <= MIN_SIZE)
			{
				return new Layout(f, lines, lineHeight);
			}
			size--;
		}
	}

	private static List<String> wrap(String text, FontMetrics fm, int width)
	{
		List<String> lines = new ArrayList<>();
		for (String paragraph : text.split("\n"))
		{
			StringBuilder line = new StringBuilder();
			for (String word : paragraph.split(" "))
			{
				if (word.isEmpty())
				{
					continue;
				}
				// A word wider than the whole box is split across lines rather than overflowing
				while (fm.stringWidth(word) > width && word.length() > 1)
				{
					int cut = word.length() - 1;
					while (cut > 1 && fm.stringWidth(word.substring(0, cut)) > width)
					{
						cut--;
					}
					if (line.length() > 0)
					{
						lines.add(line.toString());
						line.setLength(0);
					}
					lines.add(word.substring(0, cut));
					word = word.substring(cut);
				}
				String candidate = line.length() == 0 ? word : line + " " + word;
				if (line.length() > 0 && fm.stringWidth(candidate) > width)
				{
					lines.add(line.toString());
					line.setLength(0);
					line.append(word);
				}
				else
				{
					line.setLength(0);
					line.append(candidate);
				}
			}
			lines.add(line.toString());
		}
		return lines;
	}

	private static String clean(String text)
	{
		if (text == null)
		{
			return "";
		}
		// The game's line breaks are placed for its narrow font, so re-wrap instead of keeping them
		String s = BREAKS.matcher(text).replaceAll(" ");
		s = s.replace("<lt>", "\u0000lt").replace("<gt>", "\u0000gt");
		s = TAGS.matcher(s).replaceAll("");
		return s.replace("\u0000lt", "<").replace("\u0000gt", ">").replace(' ', ' ').trim();
	}

	private static synchronized Font font(boolean useBold)
	{
		if (regular == null)
		{
			regular = load("OpenDyslexic-Regular.otf");
			bold = load("OpenDyslexic-Bold.otf");
		}
		return useBold ? bold : regular;
	}

	private static Font load(String name)
	{
		try (InputStream in = BundledFontOverlay.class.getResourceAsStream(name))
		{
			return Font.createFont(Font.TRUETYPE_FONT, in);
		}
		catch (Exception e)
		{
			log.warn("Couldn't load {}, falling back to sans-serif", name, e);
			return new Font(Font.SANS_SERIF, Font.PLAIN, 12);
		}
	}

	private static final class Layout
	{
		private final Font font;
		private final List<String> lines;
		private final int lineHeight;

		private Layout(Font font, List<String> lines, int lineHeight)
		{
			this.font = font;
			this.lines = lines;
			this.lineHeight = lineHeight;
		}
	}
}

package com.cleardialogue;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(ClearDialogueConfig.GROUP)
public interface ClearDialogueConfig extends Config
{
	String GROUP = "cleardialogue";

	@ConfigSection(
		name = "Text",
		description = "Font and text colours",
		position = 0
	)
	String textSection = "text";

	@ConfigItem(
		keyName = "font",
		name = "Font",
		description = "Font used for dialogue text. Larger fonts fit fewer words per line. "
			+ "OpenDyslexic isn't a game font, so the plugin draws that text itself.",
		section = textSection,
		position = 0
	)
	default GameFont font()
	{
		return GameFont.VERDANA_13;
	}

	@Range(min = 10, max = 28)
	@ConfigItem(
		keyName = "bundledFontSize",
		name = "OpenDyslexic size",
		description = "Text size when using OpenDyslexic. Text shrinks automatically if it would not fit.",
		section = textSection,
		position = 1
	)
	default int bundledFontSize()
	{
		return 14;
	}

	@Range(min = 60, max = 150)
	@ConfigItem(
		keyName = "bundledLineSpacing",
		name = "OpenDyslexic line spacing",
		description = "Gap between lines when using OpenDyslexic, as a % of the font's normal spacing",
		section = textSection,
		position = 2
	)
	default int bundledLineSpacing()
	{
		return 80;
	}

	@ConfigItem(
		keyName = "textColor",
		name = "Dialogue text",
		description = "Dialogue and option text colour",
		section = textSection,
		position = 3
	)
	default Color textColor()
	{
		return Color.BLACK;
	}

	@ConfigItem(
		keyName = "nameColor",
		name = "Speaker name",
		description = "Colour of the speaker's name and menu titles",
		section = textSection,
		position = 4
	)
	default Color nameColor()
	{
		return new Color(0x7A, 0x00, 0x00);
	}

	@ConfigItem(
		keyName = "continueColor",
		name = "Continue prompt",
		description = "Colour of 'Click here to continue'",
		section = textSection,
		position = 5
	)
	default Color continueColor()
	{
		return new Color(0x1C, 0x3C, 0x9C);
	}

	@ConfigItem(
		keyName = "hoverColor",
		name = "Hover",
		description = "Colour of an option or prompt under the mouse",
		section = textSection,
		position = 6
	)
	default Color hoverColor()
	{
		return new Color(0x8A, 0x24, 0x00);
	}

	@ConfigItem(
		keyName = "shadow",
		name = "Text shadow",
		description = "Draw a dark shadow behind text",
		section = textSection,
		position = 7
	)
	default boolean shadow()
	{
		return false;
	}
}

package com.cleardialogue;

import com.google.inject.Provides;
import java.awt.Color;
import java.util.ArrayList;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import lombok.Getter;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Restyles the game's own dialogue widgets: font and text colours.
 *
 * No text is changed, so chat heads, item models, click areas and keyboard shortcuts all behave
 * exactly as normal. Every change is cosmetic and is undone when the dialogue closes or the plugin
 * is turned off. The one exception to "the game draws everything" is a bundled font such as
 * OpenDyslexic: the game can't draw it, so {@link BundledFontOverlay} draws the same text in the
 * same boxes and the game's copy is hidden. Clickable widgets (options, continue) are made fully
 * transparent; non-clickable ones (name, body) have their text blanked and saved, because the game
 * ignores transparency on lines after a forced line break.
 */
@PluginDescriptor(
	name = "Clear Dialogue",
	description = "Accessible dialogue boxes: OpenDyslexic or clearer game fonts, plus custom text colours",
	tags = {"dialogue", "font", "readability", "accessibility", "dyslexia", "opendyslexic", "chatbox", "colour"}
)
public class ClearDialoguePlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClearDialogueConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BundledFontOverlay bundledFontOverlay;

	/**
	 * Original styling of every widget we touched, so it can be put back.
	 */
	private final Map<Widget, Style> originals = new IdentityHashMap<>();

	/**
	 * Text of non-clickable widgets we blanked for a bundled font, so it can be drawn and put back.
	 */
	private final Map<Widget, String> blankedText = new IdentityHashMap<>();

	/**
	 * Text the overlay should draw this frame, when a bundled font is selected.
	 */
	@Getter
	private final List<DrawnText> drawnTexts = new ArrayList<>();

	@Override
	protected void startUp()
	{
		overlayManager.add(bundledFontOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(bundledFontOverlay);
		clientThread.invoke(() ->
		{
			drawnTexts.clear();
			restoreText();
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ClearDialogueConfig.GROUP.equals(event.getGroup()))
		{
			// Rebuilt with the new settings on the next frame
			clientThread.invoke(this::restoreText);
		}
	}

	/**
	 * Every chatbox dialogue made of a title/name, a body and a continue prompt.
	 * A title or continue of -1 means none, or (for continue) found by its text.
	 */
	private static final Box[] BOXES = {
		// NPC speech, player speech
		new Box(InterfaceID.ChatLeft.UNIVERSE, InterfaceID.ChatLeft.NAME, InterfaceID.ChatLeft.TEXT, InterfaceID.ChatLeft.CONTINUE),
		new Box(InterfaceID.ChatRight.UNIVERSE, InterfaceID.ChatRight.NAME, InterfaceID.ChatRight.TEXT, InterfaceID.ChatRight.CONTINUE),
		// Plain messages ("Someone throws a tomato at the recruiter."), titled messages, messages with a link
		new Box(InterfaceID.Messagebox.UNIVERSE, -1, InterfaceID.Messagebox.TEXT, InterfaceID.Messagebox.CONTINUE),
		new Box(InterfaceID.MessageboxTitled.UNIVERSE, InterfaceID.MessageboxTitled.TITLE, InterfaceID.MessageboxTitled.TEXT,
			InterfaceID.MessageboxTitled.CONTINUE),
		new Box(InterfaceID.MessageboxUrl.UNIVERSE, -1, InterfaceID.MessageboxUrl.TEXT, InterfaceID.MessageboxUrl.CONTINUE),
		// Messages with one item, two items or a picture ("You light the logs.")
		new Box(InterfaceID.Objectbox.UNIVERSE, -1, InterfaceID.Objectbox.TEXT, -1),
		new Box(InterfaceID.ObjectboxDouble.UNIVERSE, -1, InterfaceID.ObjectboxDouble.TEXT, -1),
		new Box(InterfaceID.Graphicbox.UNIVERSE, -1, InterfaceID.Graphicbox.TEXT, -1),
		// Level-up messages
		new Box(InterfaceID.LevelupDisplay.UNIVERSE, InterfaceID.LevelupDisplay.TEXT1, InterfaceID.LevelupDisplay.TEXT2,
			InterfaceID.LevelupDisplay.CONTINUE),
	};

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		drawnTexts.clear();
		boolean open = styleOptions();
		for (Box box : BOXES)
		{
			open |= styleBox(box);
		}

		if (!open && (!originals.isEmpty() || !blankedText.isEmpty()))
		{
			// Usually the game discards these widgets on close, but put everything back in case any are reused
			restoreText();
		}
	}

	private boolean styleBox(Box box)
	{
		Widget universe = visible(box.universe);
		if (universe == null)
		{
			return false;
		}
		if (box.title != -1)
		{
			style(visible(box.title), config.nameColor(), true);
		}
		Widget text = visible(box.text);
		style(text, config.textColor(), false);
		styleContinue(box.cont != -1 ? visible(box.cont) : findContinue(universe, text));
		return true;
	}

	private boolean styleOptions()
	{
		Widget options = visible(InterfaceID.Chatmenu.OPTIONS);
		if (options == null || options.getDynamicChildren() == null)
		{
			return false;
		}

		Widget[] rows = options.getDynamicChildren();
		for (int i = 0; i < rows.length; i++)
		{
			Widget row = rows[i];
			if (row == null || row.isHidden())
			{
				continue;
			}
			// Row 0 is the "Select an option" title. The game recolours hovered rows itself, but we
			// override colours every frame, so hover has to be handled here too.
			Color colour = i == 0 ? config.nameColor() : hovered(row) ? config.hoverColor() : config.textColor();
			style(row, colour, i == 0);
		}
		return true;
	}

	private void styleContinue(Widget cont)
	{
		if (cont != null)
		{
			style(cont, hovered(cont) ? config.hoverColor() : config.continueColor(), false);
		}
	}

	private void style(Widget w, Color colour, boolean bold)
	{
		if (w == null)
		{
			return;
		}
		originals.computeIfAbsent(w, Style::of);
		if (config.font().isBundled())
		{
			drawnTexts.add(new DrawnText(w, hideText(w), colour, bold));
			return;
		}
		// Only touch what differs, so the game isn't told to re-render unchanged text every frame
		int font = config.font().getFontId();
		int rgb = colour.getRGB() & 0xFFFFFF;
		if (w.getFontId() != font)
		{
			w.setFontId(font);
		}
		if (w.getTextColor() != rgb)
		{
			w.setTextColor(rgb);
		}
		if (w.getTextShadowed() != config.shadow())
		{
			w.setTextShadowed(config.shadow());
		}
	}

	/**
	 * Hides the game's copy of a widget's text and returns the text to draw instead.
	 */
	private String hideText(Widget w)
	{
		// Once blanked, stay on that path even if the widget's listeners change
		if (w.hasListener() && !blankedText.containsKey(w))
		{
			// Clickable: keep the text so nothing about the click changes, just make it fully transparent
			if (w.getOpacity() != 255)
			{
				w.setOpacity(255);
			}
			return w.getText();
		}

		String current = w.getText();
		if (current != null && !current.isEmpty())
		{
			// New text from the game (first frame, or the dialogue moved on): save it and blank the widget
			blankedText.put(w, current);
			w.setText("");
		}
		return blankedText.getOrDefault(w, "");
	}

	private void restoreText()
	{
		drawnTexts.clear();
		originals.forEach((w, s) -> s.apply(w));
		originals.clear();
		blankedText.forEach(Widget::setText);
		blankedText.clear();
	}

	/**
	 * Finds the clickable continue prompt in boxes that don't have a fixed widget for it.
	 * Only clickable widgets whose whole text is the prompt match, so body text mentioning
	 * "continue" is never mistaken for it.
	 */
	private static Widget findContinue(Widget parent, Widget exclude)
	{
		for (Widget[] group : new Widget[][]{parent.getDynamicChildren(), parent.getStaticChildren()})
		{
			if (group == null)
			{
				continue;
			}
			for (Widget w : group)
			{
				if (w == null || w == exclude || w.isHidden() || !w.hasListener() || w.getText() == null)
				{
					continue;
				}
				String t = w.getText().replaceAll("<[^>]*>", "").trim().toLowerCase();
				if (t.equals("click here to continue") || t.equals("click to continue") || t.startsWith("please wait"))
				{
					return w;
				}
			}
		}
		return null;
	}

	private boolean hovered(Widget w)
	{
		Point mouse = client.getMouseCanvasPosition();
		return mouse != null && w.getBounds().contains(mouse.getX(), mouse.getY());
	}

	private Widget visible(int componentId)
	{
		Widget w = client.getWidget(componentId);
		return w == null || w.isHidden() ? null : w;
	}

	@Value
	private static class Box
	{
		int universe;
		int title;
		int text;
		int cont;
	}

	@Value
	static class DrawnText
	{
		Widget widget;
		String text;
		Color colour;
		boolean bold;
	}

	private static final class Style
	{
		private final int font;
		private final int colour;
		private final boolean shadowed;
		private final int opacity;

		private Style(int font, int colour, boolean shadowed, int opacity)
		{
			this.font = font;
			this.colour = colour;
			this.shadowed = shadowed;
			this.opacity = opacity;
		}

		static Style of(Widget w)
		{
			return new Style(w.getFontId(), w.getTextColor(), w.getTextShadowed(), w.getOpacity());
		}

		void apply(Widget w)
		{
			w.setFontId(font);
			w.setTextColor(colour);
			w.setTextShadowed(shadowed);
			w.setOpacity(opacity);
		}
	}

	@Provides
	ClearDialogueConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ClearDialogueConfig.class);
	}
}

package com.cleardialogue;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.FontID;

/**
 * Dialogue fonts. Most ship with the game itself, so the game draws the text. Bundled fonts
 * (fontId -1) aren't in the game, so the plugin draws that text itself.
 */
@Getter
@RequiredArgsConstructor
public enum GameFont
{
	VERDANA_11("Verdana 11", FontID.VERDANA_11),
	VERDANA_13("Verdana 13", FontID.VERDANA_13),
	VERDANA_13_BOLD("Verdana 13 bold", FontID.VERDANA_13_BOLD),
	TAHOMA_11("Tahoma 11", FontID.TAHOMA_11),
	RUNESCAPE("RuneScape", FontID.PLAIN_12),
	RUNESCAPE_BOLD("RuneScape bold", FontID.BOLD_12),
	ORIGINAL("Original (Quill)", FontID.QUILL_8),
	OPENDYSLEXIC("OpenDyslexic", -1);

	private final String name;
	private final int fontId;

	public boolean isBundled()
	{
		return fontId < 0;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.cleardialogue;

import java.util.Arrays;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ClearDialoguePluginTest
{
	public static void main(String[] args) throws Exception
	{
		// loadBuiltin requires -ea, which some launchers do not pass. This must run before any RuneLite class is loaded.
		ClassLoader.getSystemClassLoader().setDefaultAssertionStatus(true);

		// Some third-party launchers pass -J<jvm arg> options meant for the official RuneLite launcher; the client rejects them
		String[] clientArgs = Arrays.stream(args)
			.filter(a -> !a.startsWith("-J"))
			.toArray(String[]::new);

		ExternalPluginManager.loadBuiltin(ClearDialoguePlugin.class);
		RuneLite.main(clientArgs);
	}
}
